#include <string>
#include <vector>

class Student {
    std::string name;
    std::vector<int> scores;

public:
    Student(std::string name, std::vector<int> scores)
        : name(std::move(name)), scores(std::move(scores)) {}

    double average() const {
        int total = 0;
        for (int score : scores) total += score;
        // Cast before dividing, otherwise int / int truncates
        return scores.empty() ? 0.0 : total / static_cast<double>(scores.size());
    }

    char letterGrade() const {
        double avg = average();
        if (avg >= 90) return 'A';
        if (avg >= 80) return 'B';
        if (avg >= 70) return 'C';
        if (avg >= 60) return 'D';
        return 'F';
    }

    std::string summary() const {
        std::string list = "[";
        for (size_t i = 0; i < scores.size(); ++i) {
            list += (i ? ", " : "") + std::to_string(scores[i]);
        }
        char avg[32];
        std::snprintf(avg, sizeof avg, "%.2f", average());
        return name + " scores=" + list + "], avg=" + avg + ", letter=" + letterGrade();
    }
};

