int main() {
    // Primitive: assignment copies the number
    int a = 5;
    int b = a;
    b = b + 10;
    std::cout << "a = " << a << ", b = " << b << " (b got a copy of the value)\n";

    // C++ would copy the whole vector on "auto y = x"; a reference (&) shares it like Java does
    std::vector<int> x = {1, 2, 3};
    std::vector<int>& y = x;
    y[0] = 99;
    std::cout << "x = " << show(x) << ", y = " << show(y) << " (y copied the reference)\n";

    const int MAX_CREDITS = 18;   // const plays the role of Java's final
    int credits = 12;
    int before = credits;
    credits += 3;
    std::cout << "credits: " << before << " -> " << credits << " (max " << MAX_CREDITS << ")\n";

    {
        int bonus = 2;            // block scope
        credits += bonus;
        std::cout << "inside block: bonus = " << bonus << ", credits = " << credits << "\n";
    }
    std::cout << "after block: credits = " << credits << " (bonus is out of scope)\n";
}

