#include <string>
#include <vector>

std::string show(const std::vector<int>& v) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) s += (i ? ", " : "") + std::to_string(v[i]);
    return s + "]";
}

int square(int n) { return n * n; }

double average(int a, int b) { return (a + b) / 2.0; }

void tryToChange(int n) {
    n = 100;  // n is a copy, exactly as in Java
    std::cout << "inside tryToChange: n = " << n << "\n";
}

// C++ copies a vector passed by value, so take a reference (&) to share it like Java
void addBonus(std::vector<int>& scores, int bonus) {
    for (int& s : scores) s += bonus;
}

// A pointer passed by value is the closest match to a Java reference parameter
void reassign(std::vector<int>* scores) {
    std::vector<int> zeros = {0, 0};
    scores = &zeros;  // rebinds the local pointer only
    std::cout << "inside reassign: " << show(*scores) << "\n";
}

int main() {
    std::cout << "square(7) = " << square(7) << "\n";
    std::printf("average(80, 95) = %.2f\n", average(80, 95));

    int n = 5;
    std::cout << "before tryToChange: n = " << n << "\n";
    tryToChange(n);
    std::cout << "after tryToChange: n = " << n << "\n";

    std::vector<int> scores = {75, 90};
    addBonus(scores, 5);
    std::cout << "after addBonus(scores, 5): " << show(scores) << "\n";
    reassign(&scores);
    std::cout << "after reassign: " << show(scores) << "\n";
}

