class Point {
    int x, y;

public:
    Point(int x, int y) : x(x), y(y) {}

    void move(int dx, int dy) {
        x += dx;
        y += dy;
    }

    // operator== plays the role of Java's equals
    bool operator==(const Point& other) const { return x == other.x && y == other.y; }

    std::string toString() const {
        return "(" + std::to_string(x) + ", " + std::to_string(y) + ")";
    }
};

int main() {
    Point p(1, 2);
    Point& q = p;   // a C++ reference is an alias; "Point q = p" would copy the object
    Point r(4, 5);
    std::cout << "p = " << p.toString() << ", q = " << q.toString() << ", r = " << r.toString() << "\n";

    q.move(3, 3);
    std::cout << "after q.move(3, 3): p = " << p.toString() << ", q = " << q.toString() << "\n";

    // Identity in C++ means comparing addresses
    std::cout << std::boolalpha;
    std::cout << "p == q (same object): " << (&p == &q) << "\n";
    std::cout << "p == r (same object): " << (&p == &r) << "\n";
    std::cout << "p.equals(r) (same contents): " << (p == r) << "\n";

    Point pts[] = {Point(0, 0), Point(0, 0)};
    pts[0].move(1, 0);
    std::cout << "pts[0] = " << pts[0].toString() << ", pts[1] = " << pts[1].toString() << "\n";
}

