public class BreakContinueLabeled {
    public static void main(String[] args) {
        int[] readings = {4, -1, 7, 0, 9};
        for (int v : readings) {
            if (v < 0) {
                System.out.println("skip " + v + " (continue)");
                continue;              // jump to the next iteration
            }
            if (v == 0) {
                System.out.println("hit 0, stop (break)");
                break;                 // leave the loop: 9 is never processed
            }
            System.out.println("process " + v);
        }

        int[][] grid = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int target = 5;

        // A label names the outer loop so break can exit both loops at once
        int checks = 0;
        search:
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                checks++;
                if (grid[r][c] == target) {
                    System.out.println("labeled break: found " + target + " at (" + r + ", " + c
                        + ") after " + checks + " checks");
                    break search;
                }
            }
        }

        // A plain break leaves only the inner loop; the outer loop keeps going
        checks = 0;
        int rowsVisited = 0;
        for (int r = 0; r < grid.length; r++) {
            rowsVisited++;
            for (int c = 0; c < grid[r].length; c++) {
                checks++;
                if (grid[r][c] == target) break;
            }
        }
        System.out.println("plain break: visited " + rowsVisited + " rows, " + checks + " checks");
    }
}

