class BankAccount {
  // # fields are enforced private: acct.#balance outside the class is a syntax error
  #owner;
  #balance;
  #history = [];

  constructor(owner, openingBalance) {
    if (openingBalance < 0) throw new RangeError('opening balance must be >= 0');
    this.#owner = owner;
    this.#balance = openingBalance;
  }

  deposit(amount) {
    if (amount <= 0) return false;
    this.#balance += amount;
    this.#history.push(`deposit ${amount.toFixed(2)}`);
    return true;
  }

  withdraw(amount) {
    if (amount <= 0 || amount > this.#balance) return false;
    this.#balance -= amount;
    this.#history.push(`withdraw ${amount.toFixed(2)}`);
    return true;
  }

  get owner() { return this.#owner; }

  get balance() { return this.#balance; }

  getHistory() { return [...this.#history]; } // defensive copy
}

function report(action, ok, acct) {
  console.log(`${action} -> ${ok ? 'ok' : 'rejected'}, balance $${acct.balance.toFixed(2)}`);
}

const acct = new BankAccount('Ana', 100.0);
console.log(`opened for ${acct.owner} with $${acct.balance.toFixed(2)}`);
report('deposit 50.00', acct.deposit(50.0), acct);
report('withdraw 200.00', acct.withdraw(200.0), acct);
report('withdraw -5.00', acct.withdraw(-5.0), acct);
