#include <cstdio>
#include <memory>
#include <string>
#include <vector>

class Shape {
public:
    virtual ~Shape() = default;
    // virtual = dynamic dispatch (Java methods are virtual by default)
    virtual double area() const { return 0; }
    virtual std::string name() const { return "Shape"; }
};

class Circle : public Shape {
    double r;

public:
    explicit Circle(double r) : r(r) {}
    double area() const override { return M_PI * r * r; }
    std::string name() const override { return "Circle"; }
};

class Rectangle : public Shape {
    double w, h;

public:
    Rectangle(double w, double h) : w(w), h(h) {}
    double area() const override { return w * h; }
    std::string name() const override { return "Rectangle"; }
};

class Square : public Rectangle {
public:
    explicit Square(double side) : Rectangle(side, side) {}
    std::string name() const override { return "Square"; }
};

// C++ overloads are resolved at compile time from the static type, exactly like Java
std::string describe(const Shape&) { return "describe(Shape) chosen"; }
std::string describe(const Circle&) { return "describe(Circle) chosen"; }

int main() {
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>(1));
    shapes.push_back(std::make_unique<Rectangle>(3, 4));
    shapes.push_back(std::make_unique<Square>(2));

