abstract class Payment {
    private final double amount;          // shared state lives in the abstract class

    protected Payment(double amount) {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        this.amount = amount;
    }

    double getAmount() { return amount; }

    abstract String method();             // no body: each subclass must supply one

    abstract double fee();

    // Template method: fixed algorithm that calls the abstract steps
    final String receipt() {
        return String.format("%-9s amount $%.2f + fee $%.2f = $%.2f",
            method() + ":", amount, fee(), amount + fee());
    }
}

class CardPayment extends Payment {
