    @Override String method() { return "Cash"; }

    @Override double fee() { return 0.0; }
}

class TransferPayment extends Payment {
    TransferPayment(double amount) { super(amount); }

    @Override String method() { return "Transfer"; }

    @Override double fee() { return 1.00; }
