import java.util.List;

public class InterfacesCapabilities {
    public static void main(String[] args) {
        List<Drawable> items = List.of(new Square(2), new Label("Hello"), new Picture(4, 3));
        for (Drawable d : items) {
            System.out.println(d.draw());
            // Capability check: only some Drawables are also Resizable
            if (d instanceof Resizable r) {
                r.scale(2);
                System.out.println("  resizable: scaled x2 -> " + d.draw() + ", area " + r.area());
            } else {
                System.out.println("  not resizable");
            }
        }
    }
}

interface Drawable {
    String draw();
}

interface Resizable {
    void scale(int factor);

    int width();

    int height();

    // default method: implementers inherit this body unless they override it
    default int area() {
        return width() * height();
    }
}

class Square implements Drawable, Resizable {   // one class, two interfaces
    private int side;

    Square(int side) { this.side = side; }

    @Override public String draw() { return "Square " + side + "x" + side; }

    @Override public void scale(int factor) { side *= factor; }

    @Override public int width() { return side; }

    @Override public int height() { return side; }
}

class Label implements Drawable {
    private final String text;

    Label(String text) { this.text = text; }

    @Override public String draw() { return "Label \"" + text + "\""; }
}

class Picture implements Drawable, Resizable {
    private int w, h;

    Picture(int w, int h) { this.w = w; this.h = h; }

    @Override public String draw() { return "Picture " + w + "x" + h; }

    @Override public void scale(int factor) { w *= factor; h *= factor; }

    @Override public int width() { return w; }

    @Override public int height() { return h; }
}

