#include <iostream>
#include <memory>
#include <string>
#include <vector>

// An "interface" in C++ is a class with only pure virtual functions
class Drawable {
public:
    virtual ~Drawable() = default;
    virtual std::string draw() const = 0;
};

class Resizable {
public:
    virtual ~Resizable() = default;
    virtual void scale(int factor) = 0;
    virtual int width() const = 0;
    virtual int height() const = 0;
    // A concrete member function plays the role of Java's default method
    int area() const { return width() * height(); }
};

// Multiple inheritance of interfaces, like "implements Drawable, Resizable"
class Square : public Drawable, public Resizable {
    int side;

public:
    explicit Square(int side) : side(side) {}
    std::string draw() const override { return "Square " + std::to_string(side) + "x" + std::to_string(side); }
    void scale(int factor) override { side *= factor; }
    int width() const override { return side; }
    int height() const override { return side; }
};

class Label : public Drawable {
    std::string text;

public:
    explicit Label(std::string text) : text(std::move(text)) {}
    std::string draw() const override { return "Label \"" + text + "\""; }
};

class Picture : public Drawable, public Resizable {
    int w, h;

public:
    Picture(int w, int h) : w(w), h(h) {}
    std::string draw() const override { return "Picture " + std::to_string(w) + "x" + std::to_string(h); }
    void scale(int factor) override { w *= factor; h *= factor; }
    int width() const override { return w; }
    int height() const override { return h; }
};

int main() {
    std::vector<std::unique_ptr<Drawable>> items;
    items.push_back(std::make_unique<Square>(2));
    items.push_back(std::make_unique<Label>("Hello"));
    items.push_back(std::make_unique<Picture>(4, 3));

