        // dynamic_cast across the hierarchy returns nullptr if the capability is missing
        if (auto* r = dynamic_cast<Resizable*>(d.get())) {
            r->scale(2);
            std::cout << "  resizable: scaled x2 -> " << d->draw() << ", area " << r->area() << "\n";
        } else {
            std::cout << "  not resizable\n";
        }
    }
}

