// JS has no type parameters; this Stack accepts anything, so type safety is up to the caller
/** @template T */
class Stack {
  #items = [];

  /** @param {T} item */
  push(item) { this.#items.push(item); }

  /** @returns {T} */
  pop() {
    if (this.#items.length === 0) throw new RangeError('stack is empty');
    return this.#items.pop();
  }

  isEmpty() { return this.#items.length === 0; }

  toString() { return `[${this.#items.join(', ')}]`; }
}

/** @template A, B */
class Pair {
  constructor(first, second) {
    this.first = first;
    this.second = second;
    Object.freeze(this); // immutable, like a Java record
  }

  swap() { return new Pair(this.second, this.first); }

  toString() { return `(${this.first}, ${this.second})`; }
}

