// Function templates: T is deduced from the arguments at each call
template <typename T>
void swapAt(std::vector<T>& a, size_t i, size_t j) {
    T tmp = a[i];
    a[i] = a[j];
    a[j] = tmp;
}

template <typename T>
std::vector<T> repeat(const T& value, int times) {
    return std::vector<T>(times, value);
}

template <typename T>
T firstOrDefault(const std::vector<T>& list, const T& fallback) {
    return list.empty() ? fallback : list[0];
}

template <typename T>
std::string show(const std::vector<T>& v) {
    std::ostringstream out;
    out << "[";
    for (size_t i = 0; i < v.size(); ++i) out << (i ? ", " : "") << v[i];
    out << "]";
    return out.str();
}

int main() {
    std::vector<std::string> colors = {"red", "green", "blue"};
    std::cout << "before swap: " << show(colors) << "\n";
    swapAt(colors, 0, 2);
    std::cout << "swap(colors, 0, 2): " << show(colors) << "\n";

    std::vector<int> nums = {1, 2, 3};  // templates also work with primitives
    swapAt(nums, 1, 2);
    std::cout << "swap(nums, 1, 2): " << show(nums) << "\n";

    std::cout << "repeat(\"ab\", 3): " << show(repeat(std::string("ab"), 3)) << "\n";
    std::cout << "repeat(7, 2): " << show(repeat(7, 2)) << "\n";

    std::vector<std::string> empty;
    std::vector<std::string> xy = {"x", "y"};
    std::cout << "firstOrDefault([], \"none\"): " << firstOrDefault(empty, std::string("none")) << "\n";
    std::cout << "firstOrDefault([x, y], \"none\"): " << firstOrDefault(xy, std::string("none")) << "\n";

