// Stand-ins for org.junit.jupiter.api.Assertions (expected first, as in JUnit)
class AssertionError extends Error {}

function assertEquals(expected, actual, delta = 0) {
  if (Math.abs(expected - actual) > delta) throw new AssertionError(`expected: <${expected}> but was: <${actual}>`);
}
function assertTrue(condition) {
  if (!condition) throw new AssertionError('expected: <true> but was: <false>');
}
function assertThrows(type, code) {
  try { code(); } catch (e) { if (e instanceof type) return; throw e; }
  throw new AssertionError('expected an exception, but nothing was thrown');
}

// The class under test
class Calculator {
  add(a, b) { return a + b; }
  divide(a, b) {
    if (b === 0) throw new RangeError('/ by zero'); // JS would silently return Infinity
    return a / b;
  }
  isEven(n) { return n % 2 === 0; }
  max(...values) {
    let best = 0; // BUG: should start at values[0]; the test below catches it
    for (const v of values) best = Math.max(best, v);
    return best;
  }
}

class CalculatorTest {
  setUp() { this.calculator = new Calculator(); } // plays the role of @BeforeEach
  addition() { assertEquals(5, this.calculator.add(2, 3)); assertEquals(0, this.calculator.add(-1, 1)); }
  division() { assertEquals(2.5, this.calculator.divide(10, 4), 1e-9); }
  divideByZero() { assertThrows(RangeError, () => this.calculator.divide(10, 0)); }
  evens(n) { assertTrue(this.calculator.isEven(n)); }
  maxOfNegatives() { assertEquals(-2, this.calculator.max(-5, -2, -9)); }
}

// JavaScript has no annotations, so the test metadata is a table (like @Test/@DisplayName/@ValueSource)
const tests = [
  { name: 'add two numbers', method: 'addition' },
  { name: 'divide within delta', method: 'division' },
  { name: 'divide by zero throws', method: 'divideByZero' },
  { name: 'isEven', method: 'evens', values: [2, 4, 6, 8] },
  { name: 'max of all-negative array', method: 'maxOfNegatives' },
];

// A tiny runner: new instance per test, setUp, then report
function runTests(cls, specs) {
  let run = 0;
  let failed = 0;
  console.log(cls.name);
  for (const spec of [...specs].sort((a, b) => (a.name < b.name ? -1 : 1))) { // deterministic demo order
    const invocations = spec.values ? spec.values.map((v) => [v]) : [[]];
    invocations.forEach((args, i) => {
      const label = args.length ? `${spec.name} [${i + 1}] ${args[0]}` : spec.name;
      const instance = new cls(); // fresh object for every test
      run += 1;
      try {
        instance.setUp();
        instance[spec.method](...args);
        console.log(`  PASS  ${label}`);
      } catch (e) {
        if (!(e instanceof AssertionError)) throw e;
        failed += 1;
        console.log(`  FAIL  ${label}`);
        console.log(`        ${e.message}`);
      }
    });
  }
  console.log(`Tests run: ${run}, passed: ${run - failed}, failed: ${failed}`);
}

runTests(CalculatorTest, tests);

