# In Python you would use pytest or unittest; here a tiny runner mirrors what JUnit does.


def test(display_name):  # plays the role of @Test @DisplayName("...")
    def mark(fn):
        fn.display_name = display_name
        return fn
    return mark


def assert_equals(expected, actual):  # expected first, as in JUnit
    if expected != actual:
        raise AssertionError(f"expected: <{expected}> but was: <{actual}>")


def count_words(text):
    """Code under test: counts words, but only treats ' ' as a separator (a real bug)."""
    words, in_word = 0, False
    for c in text:
        if c == " ":
            in_word = False
        elif not in_word:
            in_word, words = True, words + 1
    return words


class WordCounterTest:
    # Each test is a no-argument method that follows Arrange-Act-Assert
    @test("counts words separated by spaces")
    def counts_words_separated_by_spaces(self):
        text = "unit tests are fun"      # arrange
        result = count_words(text)       # act
        assert_equals(4, result)         # assert

    @test("empty string has zero words")
    def empty_string_has_zero_words(self):
        assert_equals(0, count_words(""))

    @test("ignores leading, trailing and repeated spaces")
    def ignores_extra_spaces(self):
        assert_equals(2, count_words("  two   words "))

    @test("treats a tab as a separator")
    def tab_is_a_separator(self):
        assert_equals(2, count_words("one\ttwo"))


def run_tests(cls):
    """What the JUnit engine does: find marked methods, run each one in isolation, collect results."""
    tests = sorted((f for f in vars(cls).values() if hasattr(f, "display_name")), key=lambda f: f.__name__)
    failed = 0
    print(cls.__name__)
    for fn in tests:
        try:
            fn(cls())
            print(f"  PASS  {fn.display_name}")
        except AssertionError as e:  # a failing test does not stop the others
            failed += 1
            print(f"  FAIL  {fn.display_name}")
            print(f"        {e}")
    print(f"Tests run: {len(tests)}, passed: {len(tests) - failed}, failed: {failed}")


