const failures = (version, suite) =>
  suite.filter(([year, expected]) => version.isLeap(year) !== expected).map(([year]) => year);

function run(phase, version, suite) {
  const failed = failures(version, suite);
  const status = failed.length === 0 ? 'GREEN' : 'RED  ';
  const detail = failed.length === 0 ? `all ${suite.length} tests pass` : `failed [${failed.join(', ')}]`;
  console.log(`  ${phase} ${status} ${version.name}: ${detail}`);
}

// Each implementation is the smallest change that makes the newest test pass
const v0 = { name: 'v0 always false', isLeap: () => false };
const v1 = { name: 'v1 divisible by 4', isLeap: (y) => y % 4 === 0 };
const v2 = { name: 'v2 by 4 but not by 100', isLeap: (y) => y % 4 === 0 && y % 100 !== 0 };
