// Mirrors java.sql.Driver: each vendor ships one implementation
class PrefixDriver {
  constructor(name, prefix) {
    this.name = name;
    this.prefix = prefix;
  }
  acceptsURL(url) { return url.startsWith(this.prefix); }
  connect(url) { return { driver: this.name, database: url.slice(this.prefix.length) }; }
}

const DriverManager = {
  drivers: [],
  // Real Java drivers are registered automatically via ServiceLoader (META-INF/services/java.sql.Driver)
  registerDriver(driver) { this.drivers.push(driver); },
  getConnection(url) {
    const driver = this.drivers.find((d) => d.acceptsURL(url)); // first driver that accepts wins
    if (!driver) throw new SQLException(`No suitable driver found for ${url}`);
    return driver.connect(url);
  },
};

DriverManager.registerDriver(new PrefixDriver('MemDriver', 'jdbc:mem:'));
DriverManager.registerDriver(new PrefixDriver('CsvDriver', 'jdbc:csv:'));
console.log('registered drivers: MemDriver, CsvDriver');

