import java.util.Map;
import java.util.TreeMap;

public class ConnectionTransactionDemo {
    public static void main(String[] args) {
        Connection kept;
        // Real: try (Connection conn = DriverManager.getConnection(url, user, password))
        try (Connection conn = new Connection(Map.of("A", 100, "B", 50))) {
            kept = conn;
            System.out.println("open: autoCommit = " + conn.getAutoCommit() + ", isClosed = " + conn.isClosed());
            Statement st = conn.createStatement();
            st.executeUpdate("UPDATE accounts SET balance = balance + 10 WHERE id = 'A'");
            System.out.println("auto-commit deposit of 10 into A -> committed " + conn.snapshot());

            conn.setAutoCommit(false);
            st.executeUpdate("UPDATE accounts SET balance = balance - 30 WHERE id = 'A'");
            st.executeUpdate("UPDATE accounts SET balance = balance + 30 WHERE id = 'B'");
            System.out.println("tx 1: moved 30 A->B, not committed yet -> committed " + conn.snapshot());
            conn.commit();
            System.out.println("tx 1: commit() -> committed " + conn.snapshot());

            try {
                st.executeUpdate("UPDATE accounts SET balance = balance + 500 WHERE id = 'B'");
                st.executeUpdate("UPDATE accounts SET balance = balance - 500 WHERE id = 'A'");
                conn.commit();
            } catch (SQLException e) {
                System.out.println("tx 2: credit B 500 ok, debit A 500 -> SQLException: " + e.getMessage());
                conn.rollback();
                System.out.println("tx 2: rollback() -> committed " + conn.snapshot() + " (the credit to B was undone)");
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
        System.out.println("after try-with-resources: isClosed = " + kept.isClosed());
        try {
            kept.createStatement();
        } catch (SQLException e) {
            System.out.println("createStatement() after close -> SQLException: " + e.getMessage());
        }
    }
}

class SQLException extends Exception {
    SQLException(String message) { super(message); }
}

// Stand-in for java.sql.Connection over one in-memory table: accounts(id, balance CHECK (balance >= 0))
class Connection implements AutoCloseable {
    private Map<String, Integer> committed;
    private Map<String, Integer> pending; // working copy while a transaction is open
    private boolean autoCommit = true, closed = false;

    Connection(Map<String, Integer> initial) { committed = new TreeMap<>(initial); }

    boolean getAutoCommit() { return autoCommit; }
    void setAutoCommit(boolean on) { autoCommit = on; }
    boolean isClosed() { return closed; }
    String snapshot() { return "A=" + committed.get("A") + " B=" + committed.get("B"); }

    Statement createStatement() throws SQLException {
        if (closed) throw new SQLException("Connection is closed");
        return new Statement(this);
    }

    void apply(String id, int delta) throws SQLException {
        if (pending == null) pending = new TreeMap<>(committed); // first write opens a transaction
        int next = pending.get(id) + delta;
        if (next < 0) throw new SQLException("CHECK constraint failed: balance >= 0");
        pending.put(id, next);
        if (autoCommit) commit(); // auto-commit: every statement is its own transaction
    }

    void commit() { if (pending != null) committed = pending; pending = null; }
    void rollback() { pending = null; }
    public void close() { pending = null; closed = true; }
}

class Statement {
    private final Connection conn;
    Statement(Connection conn) { this.conn = conn; }

    // Understands one shape: UPDATE accounts SET balance = balance <+|-> <n> WHERE id = '<id>'
    int executeUpdate(String sql) throws SQLException {
        String[] t = sql.split(" ");
        int amount = Integer.parseInt(t[7]);
        conn.apply(t[11].replace("'", ""), t[6].equals("+") ? amount : -amount);
        return 1;
    }
}

