class Connection:
    """Stand-in for java.sql.Connection over one table: accounts(id, balance CHECK (balance >= 0))."""

    def __init__(self, initial):
        self.committed, self.pending = dict(initial), None  # pending: working copy of an open transaction
        self.auto_commit, self.closed = True, False

    def getAutoCommit(self):
        return self.auto_commit

    def setAutoCommit(self, on):
        self.auto_commit = on

    def isClosed(self):
        return self.closed

    def snapshot(self):
        return f"A={self.committed['A']} B={self.committed['B']}"

    def createStatement(self):
        if self.closed:
            raise SQLException("Connection is closed")
        return Statement(self)

    def apply(self, account, delta):
        if self.pending is None:
            self.pending = dict(self.committed)  # first write opens a transaction
        new_balance = self.pending[account] + delta
        if new_balance < 0:
            raise SQLException("CHECK constraint failed: balance >= 0")
        self.pending[account] = new_balance
        if self.auto_commit:
            self.commit()  # auto-commit: every statement is its own transaction

    def commit(self):
        if self.pending is not None:
            self.committed = self.pending
        self.pending = None

    def rollback(self):
        self.pending = None

    def close(self):
        self.pending, self.closed = None, True

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()


