// Stand-in for java.sql.Connection over one table: accounts(id, balance CHECK (balance >= 0))
class Connection {
  constructor(initial) {
    this.committed = { ...initial };
    this.pending = null; // working copy while a transaction is open
    this.autoCommit = true;
    this.closed = false;
  }
  getAutoCommit() { return this.autoCommit; }
  setAutoCommit(on) { this.autoCommit = on; }
  isClosed() { return this.closed; }
  snapshot() { return `A=${this.committed.A} B=${this.committed.B}`; }

  createStatement() {
    if (this.closed) throw new SQLException('Connection is closed');
    return new Statement(this);
  }

  apply(id, delta) {
    if (this.pending === null) this.pending = { ...this.committed }; // first write opens a transaction
    const next = this.pending[id] + delta;
    if (next < 0) throw new SQLException('CHECK constraint failed: balance >= 0');
    this.pending[id] = next;
    if (this.autoCommit) this.commit(); // auto-commit: every statement is its own transaction
  }

  commit() {
    if (this.pending !== null) this.committed = this.pending;
    this.pending = null;
  }
  rollback() { this.pending = null; }
  close() {
    this.pending = null;
    this.closed = true;
  }
}

