import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class StatementMethodsDemo {
    public static void main(String[] args) {
        Statement st = new Statement(); // real: Statement st = conn.createStatement();

        boolean isQuery = st.execute("CREATE TABLE courses (code, credits)");
        System.out.println("execute(CREATE TABLE ...) -> " + isQuery + ", getUpdateCount() = " + st.getUpdateCount());

        st.addBatch("INSERT INTO courses VALUES ('CS101', 4)");
        st.addBatch("INSERT INTO courses VALUES ('CS102', 4)");
        st.addBatch("INSERT INTO courses VALUES ('CS201', 3)");
        System.out.println("executeBatch() of 3 INSERTs -> " + Arrays.toString(st.executeBatch()));

        int changed = st.executeUpdate("UPDATE courses SET credits = 5 WHERE credits = 4");
        System.out.println("executeUpdate(UPDATE ... WHERE credits = 4) -> " + changed + " rows changed");
        changed = st.executeUpdate("UPDATE courses SET credits = 6 WHERE code = 'CS999'");
        System.out.println("executeUpdate(UPDATE ... WHERE code = 'CS999') -> " + changed + " rows changed");

        ResultSet rs = st.executeQuery("SELECT code, credits FROM courses");
        System.out.println("executeQuery(SELECT code, credits FROM courses):");
        while (rs.next()) System.out.println("  " + rs.getString(1) + " " + rs.getString(2));

        isQuery = st.execute("SELECT code, credits FROM courses");
        System.out.println("execute(SELECT ...) -> " + isQuery + ", getResultSet() has " + st.getResultSet().size() + " rows");
    }
}

class ResultSet {
    private final List<List<String>> rows;
    private int cursor = -1;
    ResultSet(List<List<String>> rows) { this.rows = rows; }
    boolean next() { return ++cursor < rows.size(); }
    String getString(int column) { return rows.get(cursor).get(column - 1); } // 1-based
    int size() { return rows.size(); }
}

// Stand-in for java.sql.Statement plus a toy engine for exactly four SQL shapes; values are stored as text
class Statement {
    private List<String> columns = new ArrayList<>();
    private final List<List<String>> table = new ArrayList<>();
    private final List<String> batch = new ArrayList<>();
    private ResultSet lastResult;
    private int lastCount = -1;

    private static String value(String token) { return token.replace("'", ""); }

    private Object run(String sql) {
        String[] t = sql.split(" ");
        String inParens = sql.contains("(") ? sql.substring(sql.indexOf('(') + 1, sql.lastIndexOf(')')) : "";
        switch (t[0]) {
            case "CREATE": columns = List.of(inParens.split(", ")); return 0;
            case "INSERT": {
                List<String> row = new ArrayList<>();
                for (String v : inParens.split(", ")) row.add(value(v));
                table.add(row);
                return 1;
            }
            case "UPDATE": { // UPDATE t SET col = v WHERE col = v
                int set = columns.indexOf(t[3]), where = columns.indexOf(t[7]), count = 0;
                for (List<String> row : table) {
                    if (row.get(where).equals(value(t[9]))) { row.set(set, value(t[5])); count++; }
                }
                return count;
            }
            default: return new ResultSet(table); // SELECT code, credits FROM t (all columns, all rows)
        }
    }

    boolean execute(String sql) {
        Object result = run(sql);
        lastResult = result instanceof ResultSet rs ? rs : null;
        lastCount = result instanceof Integer n ? n : -1;
        return lastResult != null;
    }
    int getUpdateCount() { return lastCount; }
    ResultSet getResultSet() { return lastResult; }
    int executeUpdate(String sql) { return (Integer) run(sql); }
    ResultSet executeQuery(String sql) { return (ResultSet) run(sql); }
    void addBatch(String sql) { batch.add(sql); }
    int[] executeBatch() {
        int[] counts = new int[batch.size()];
        for (int i = 0; i < counts.length; i++) counts[i] = executeUpdate(batch.get(i));
        batch.clear();
        return counts;
    }
}

