class ResultSet:
    def __init__(self, rows):
        self.rows, self.cursor = rows, -1  # before the first row

    def next(self):
        self.cursor += 1
        return self.cursor < len(self.rows)

    def getString(self, column):
        return self.rows[self.cursor][column - 1]  # 1-based


def value(token):
    return token.replace("'", "")


class Statement:
    """Stand-in for java.sql.Statement plus a toy engine for exactly four SQL shapes; values are text."""

    def __init__(self):
        self.columns, self.table, self.batch = [], [], []
        self.last_result, self.last_count = None, -1

    def _run(self, sql):
        t = sql.split(" ")
        in_parens = sql[sql.find("(") + 1:sql.rfind(")")] if "(" in sql else ""
        if t[0] == "CREATE":
            self.columns = in_parens.split(", ")
            return 0
        if t[0] == "INSERT":
            self.table.append([value(v) for v in in_parens.split(", ")])
            return 1
        if t[0] == "UPDATE":  # UPDATE t SET col = v WHERE col = v
            set_col, where_col = self.columns.index(t[3]), self.columns.index(t[7])
            matches = [row for row in self.table if row[where_col] == value(t[9])]
            for row in matches:
                row[set_col] = value(t[5])
            return len(matches)
        return ResultSet(self.table)  # SELECT code, credits FROM t: all columns, all rows

    def execute(self, sql):
        result = self._run(sql)
        is_query = isinstance(result, ResultSet)
        self.last_result, self.last_count = (result, -1) if is_query else (None, result)
