// 'text' is a literal, anything else a column
const operand = (token, user) => (token.startsWith("'") ? token.slice(1, -1) : user[token]);

// Toy engine for "SELECT name, role FROM users WHERE a = b [OR c = d ...]": it parses whatever text it gets
function runSql(sql) {
  const clauses = sql.slice(sql.indexOf(' WHERE ') + 7).split(' OR ');
  return USERS.filter((user) => clauses.some((clause) => {
    const eq = clause.indexOf('=');
    return operand(clause.slice(0, eq).trim(), user) === operand(clause.slice(eq + 1).trim(), user);
  }));
}

// DON'T: user input becomes part of the SQL text
const byConcatenation = (input) => "SELECT name, role FROM users WHERE name = '" + input + "'";

// Stand-in for java.sql.PreparedStatement: the SQL shape is fixed; parameters are only data
class PreparedStatement {
  constructor(sql) {
    this.column = sql.slice(sql.indexOf(' WHERE ') + 7, sql.indexOf(' = ?'));
    this.params = {};
  }
  setString(index, value) {
    if (index < 1 || index > 1) throw new SQLException(`parameter index ${index} is out of range 1..1`);
    this.params[index] = value;
  }
  executeQuery() {
    return USERS.filter((u) => u[this.column] === this.params[1]); // plain value comparison
  }
}

const show = (users) => `[${users.map((u) => `${u.name}/${u.role}`).join(', ')}]`;

const ps = new PreparedStatement('SELECT name, role FROM users WHERE name = ?');
for (const input of ['bob', "' OR '1'='1"]) {
  console.log(`input: ${input}`);
  const sql = byConcatenation(input);
  console.log(`  concatenated SQL: ${sql}`);
  console.log(`  concatenated -> ${show(runSql(sql))}`);
  ps.setString(1, input);
  console.log(`  prepared     -> ${show(ps.executeQuery())}`);
}
try {
  ps.setString(0, 'bob');
} catch (e) {
  console.log(`setString(0, ...) -> SQLException: ${e.message}`);
}

