    std::vector<std::string> program = synced ? std::vector<std::string>{"lock", "read", "write", "unlock"}
                                              : std::vector<std::string>{"read", "write"};
    const std::size_t len = program.size();
    int count = 0;
    std::string owner;
    std::size_t pc[2] = {0, 0};
    int reg[2] = {0, 0};
    for (int turn = 0; pc[0] < len || pc[1] < len; turn = 1 - turn) {
        int t = turn;
        std::string name = "T" + std::to_string(t + 1);
        if (pc[t] == len) continue;
        const std::string& op = program[pc[t]];
        if (op == "lock") {
            if (!owner.empty()) {
                std::cout << name << " blocks: lock held by " << owner << "\n";
                continue; // loses its turn without advancing
            }
            owner = name;
            std::cout << name << " acquires the lock\n";
        } else if (op == "read") {
            reg[t] = count;
