        } else if (op == "write") {
            count = reg[t] + 1;
            std::cout << name << " writes " << reg[t] << " + 1 = " << count << "\n";
        } else {
            owner.clear();
            std::cout << name << " releases the lock\n";
        }
        ++pc[t];
    }
    return count;
}

class SyncCounter {
public:
    void increment() {
        std::lock_guard<std::mutex> guard(mutex_); // unlocks automatically, even on exceptions
