const { Worker, isMainThread, workerData } = require('node:worker_threads');

// Shared memory layout: [lock of account 1, lock of account 2, balance 1, balance 2, transfers]
const LOCK = { 1: 0, 2: 1 };
const BALANCE = { 1: 2, 2: 3 };
const TRANSFERS = 4;

function lock(cells, i) {
  while (Atomics.compareExchange(cells, i, 0, 1) !== 0) Atomics.wait(cells, i, 1);
}

function unlock(cells, i) {
  Atomics.store(cells, i, 0);
  Atomics.notify(cells, i, 1);
}

// One global rule: lower id first. Opposite transfers then cannot wait on each other in a cycle.
const lockOrder = (from, to) => (from < to ? [from, to] : [to, from]);

function transfer(cells, from, to, amount) {
  const [first, second] = lockOrder(from, to);
  lock(cells, LOCK[first]);
  lock(cells, LOCK[second]);
  cells[BALANCE[from]] -= amount; // debit and credit happen together or not at all
  cells[BALANCE[to]] += amount;
  unlock(cells, LOCK[second]);
  unlock(cells, LOCK[first]);
  Atomics.add(cells, TRANSFERS, 1); // atomic counter, no lock needed
}

if (isMainThread) {
  const cells = new Int32Array(new SharedArrayBuffer(4 * 5));
  cells[BALANCE[1]] = 1000;
  cells[BALANCE[2]] = 1000;
  console.log('naive order: T1 holds 1 wants 2, T2 holds 2 wants 1 -> deadlock possible');
  console.log(`transfer 1->2 locks: ${lockOrder(1, 2).join(', ')}`);
  console.log(`transfer 2->1 locks: ${lockOrder(2, 1).join(', ')}`);

  const jobs = [{ from: 1, to: 2, amount: 1 }, { from: 2, to: 1, amount: 2 }];
  const exited = jobs.map((job) => {
    const worker = new Worker(__filename, { workerData: { cells, ...job } });
    return new Promise((resolve) => worker.on('exit', resolve));
  });
  Promise.all(exited).then(() => {
    const [a, b] = [cells[BALANCE[1]], cells[BALANCE[2]]];
    console.log(`account 1 = ${a} (1000 - 500*1 + 500*2 = 1500)`);
    console.log(`account 2 = ${b} (1000 + 500*1 - 500*2 = 500)`);
    console.log(`total = ${a + b} (invariant: 2000)`);
    console.log(`transfers counted = ${cells[TRANSFERS]}`);
  });
} else {
  const { cells, from, to, amount } = workerData;
  for (let i = 0; i < 500; i++) transfer(cells, from, to, amount);
}

