struct Screen {
    std::vector<char> pixels = std::vector<char>(1024); // retained for as long as the Screen is owned
    void onEvent(const std::string&) { /* would repaint */ }
};

class EventBus {
public:
    void registerListener(std::shared_ptr<Screen> s) { listeners_.push_back(std::move(s)); }
    void unregisterListener(const std::shared_ptr<Screen>& s) {
        listeners_.erase(std::remove(listeners_.begin(), listeners_.end(), s), listeners_.end());
    }
    std::size_t size() const { return listeners_.size(); }
    std::size_t publish(const std::string& event) {
        for (auto& l : listeners_) l->onEvent(event);
        return listeners_.size();
    }

private:
    std::vector<std::shared_ptr<Screen>> listeners_; // shared ownership keeps every Screen alive
};

// Global buses live as long as the program, so everything they own does too
EventBus leakyBus, fixedBus;

void openAndCloseScreens(EventBus& bus, int count, bool unregisterOnClose) {
    for (int i = 0; i < count; ++i) {
        auto screen = std::make_shared<Screen>();
        bus.registerListener(screen);
        // ... the screen is shown and then closed ...
        if (unregisterOnClose) bus.unregisterListener(screen);
    }
}

// Minimal LRU cache: the list keeps keys from least to most recently used
struct LruCache {
    std::size_t capacity;
    std::list<std::string> order;
    std::map<std::string, std::string> values;

    void touch(const std::string& key) {
        order.remove(key);
        order.push_back(key);
    }
    void put(const std::string& key, const std::string& value) {
        values[key] = value;
        touch(key);
        if (order.size() > capacity) {
            values.erase(order.front()); // evict the least recently used entry
            order.pop_front();
        }
    }
    void get(const std::string& key) { if (values.count(key)) touch(key); }
    std::string keys() const {
        std::string out = "[";
        for (const auto& k : order) out += (out.size() > 1 ? ", " : "") + k;
        return out + "]";
    }
};

int main() {
    openAndCloseScreens(leakyBus, 5, false);
    std::size_t delivered = leakyBus.publish("theme-changed");
    std::cout << "leaky: 5 closed screens, bus holds " << leakyBus.size() << " listeners = " << leakyBus.size() * 1024 << " bytes still reachable\n";
    std::cout << "leaky: one event was delivered to " << delivered << " closed screens\n";
    openAndCloseScreens(fixedBus, 5, true);
    std::cout << "fixed: 5 closed screens, bus holds " << fixedBus.size() << " listeners = " << fixedBus.size() * 1024 << " bytes still reachable\n";

    std::map<std::string, std::string> unbounded;
    LruCache lru{3, {}, {}};
    for (int i = 1; i <= 8; ++i) {
        unbounded["req-" + std::to_string(i)] = "response-" + std::to_string(i);
        lru.put("req-" + std::to_string(i), "response-" + std::to_string(i));
    }
    std::cout << "unbounded cache after 8 requests: " << unbounded.size() << " entries\n";
    std::cout << "LRU cache (max 3) after 8 requests: " << lru.keys() << "\n";
    lru.get("req-6"); // a read makes req-6 the most recently used
    lru.put("req-9", "response-9");
    std::cout << "after get(req-6) and put(req-9): " << lru.keys() << "\n";
}

