#include <algorithm>
#include <cstdio>
#include <functional>
#include <string>
#include <utility>
#include <vector>

struct Item {
    std::string name;
    double price;
};

// Any callable double -> double is a strategy
using PricingStrategy = std::function<double(double)>;

// A strategy can be a class (a functor) when it has its own state
struct PercentOff {
    double percent;
    double operator()(double subtotal) const { return subtotal * (100 - percent) / 100; }
};

// The context: uses whatever strategy it was given, with no if/switch on discount type
class Checkout {
    PricingStrategy strategy;
public:
    explicit Checkout(PricingStrategy s) : strategy(std::move(s)) {}
    void setStrategy(PricingStrategy s) { strategy = std::move(s); }
    double total(const std::vector<Item>& items) const {
        double subtotal = 0;
        for (const auto& item : items) subtotal += item.price;
        return strategy(subtotal);
    }
};

std::string show(const std::vector<Item>& items) {
    std::string out;
    char buf[64];
    for (const auto& i : items) {
        std::snprintf(buf, sizeof buf, "%s%s %.2f", out.empty() ? "" : ", ", i.name.c_str(), i.price);
        out += buf;
    }
    return out;
}

int main() {
    std::vector<Item> cart = {{"book", 30.00}, {"pen", 2.50}, {"bag", 47.50}};
    std::printf("cart: %s\n", show(cart).c_str());

    std::vector<std::pair<std::string, PricingStrategy>> strategies = {
        {"regular", [](double subtotal) { return subtotal; }},
        {"student", PercentOff{10}},
        {"clearance", [](double subtotal) { return subtotal >= 50 ? subtotal - 15 : subtotal; }},
    };

    Checkout checkout(strategies[0].second);
    for (const auto& [name, strategy] : strategies) {
        checkout.setStrategy(strategy);  // swap behavior at run time
        std::printf("%-9s -> %.2f\n", name.c_str(), checkout.total(cart));
    }

    // The comparator of std::sort is the standard library's built-in Strategy hook
    auto sorted = cart;
    std::sort(sorted.begin(), sorted.end(), [](const Item& a, const Item& b) { return a.price < b.price; });
    std::printf("items by price: %s\n", show(sorted).c_str());
    std::sort(sorted.begin(), sorted.end(), [](const Item& a, const Item& b) { return a.name < b.name; });
    std::printf("items by name: %s\n", show(sorted).c_str());
}

