#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

struct Task {
    std::string title;
    bool done = false;
};

// Model: the data and its rules. It never prints and knows nothing about the view.
class TodoModel {
    std::vector<Task> tasks_;
    std::vector<std::function<void()>> listeners;  // Observer hook for views
    void notify() { for (auto& l : listeners) l(); }
public:
    void onChange(std::function<void()> l) { listeners.push_back(std::move(l)); }
    const std::vector<Task>& tasks() const { return tasks_; }

    void add(const std::string& title) {
        if (title.find_first_not_of(' ') == std::string::npos) throw std::invalid_argument("title must not be empty");
        tasks_.push_back({title, false});
        notify();
    }

    void complete(int number) {  // numbers shown to users start at 1
        if (number < 1 || number > static_cast<int>(tasks_.size()))
            throw std::invalid_argument("no task number " + std::to_string(number));
        tasks_[number - 1].done = true;
        notify();
    }
};

// View: only turns model data into text. Swapping it for a GUI would not touch the model.
struct TodoView {
    void render(const std::vector<Task>& tasks) const {
        int done = 0;
        for (size_t i = 0; i < tasks.size(); ++i) {
            std::cout << (tasks[i].done ? "[x] " : "[ ] ") << i + 1 << ". " << tasks[i].title << "\n";
            done += tasks[i].done;
        }
        std::cout << "    " << done << " of " << tasks.size() << " done\n";
    }
    void showError(const std::string& message) const { std::cout << "error: " << message << "\n"; }
};

// Controller: turns user input into model calls and routes errors to the view
class TodoController {
    TodoModel& model;
    const TodoView& view;
public:
    TodoController(TodoModel& m, const TodoView& v) : model(m), view(v) {}

