from dataclasses import dataclass


@dataclass(frozen=True)
class Task:
    title: str
    done: bool = False


class TodoModel:
    """Model: the data and its rules. It never prints and knows nothing about the view."""
    def __init__(self):
        self._tasks: list[Task] = []
        self._listeners = []  # Observer hook for views

    def on_change(self, listener):
        self._listeners.append(listener)

    def tasks(self):
        return list(self._tasks)

    def add(self, title):
        if not title.strip():
            raise ValueError("title must not be empty")
        self._tasks.append(Task(title))
        self._notify()

    def complete(self, number):  # numbers shown to users start at 1
        if not 1 <= number <= len(self._tasks):
            raise ValueError(f"no task number {number}")
        self._tasks[number - 1] = Task(self._tasks[number - 1].title, True)
        self._notify()

    def _notify(self):
        for listener in self._listeners:
            listener()


class TodoView:
    """View: only turns model data into text. Swapping it for a GUI would not touch the model."""
    def render(self, tasks):
        for i, t in enumerate(tasks, start=1):
            print(f"{'[x]' if t.done else '[ ]'} {i}. {t.title}")
        print(f"    {sum(t.done for t in tasks)} of {len(tasks)} done")

    def show_error(self, message):
        print(f"error: {message}")


class TodoController:
    """Controller: turns user input into model calls and routes errors to the view."""
    def __init__(self, model, view):
        self.model, self.view = model, view

    def handle(self, line):
        print(f"> {line}")
        command, _, argument = line.partition(" ")
        try:
            if command == "add":
                self.model.add(argument)
            elif command == "done":
                self.model.complete(int(argument))
            else:
                self.view.show_error(f"unknown command '{command}'")
        except ValueError as e:
            self.view.show_error(str(e))


