    : refl && anti && trans ? 'partial order' : 'neither';
  console.log(`  reflexive=${yesNo(refl)} symmetric=${yesNo(sym)} antisymmetric=${yesNo(anti)} ` +
    `transitive=${yesNo(trans)} -> ${kind}`);
  if (!trans) {
    const [x, y, z] = broken[0];
    console.log(`  not transitive: ${pairText(x, y)} and ${pairText(y, z)} are in R but ${pairText(x, z)} is not`);
  }
  if (kind === 'equivalence relation') {
    // Each element's related set is its class; the classes partition A
    const seen = new Set();
    const classes = [];
    for (const x of A) {
      if (seen.has(x)) continue;
      const cls = A.filter((y) => r(x, y));
      cls.forEach((y) => seen.add(y));
      classes.push(`{${cls.join(', ')}}`);
    }
    console.log(`  classes: ${classes.join(' ')}`);
  }
}

