using namespace std;

// Campus map: buildings are vertices, footpaths are undirected edges
map<string, vector<string>> adj;

string join(const vector<string>& items, const string& sep) {
    string out;
    for (size_t i = 0; i < items.size(); i++) out += (i ? sep : "") + items[i];
    return out;
}

void dfs(const string& u, set<string>& seen, vector<string>& order) {
    seen.insert(u);
    order.push_back(u);
    for (const string& w : adj[u]) if (!seen.count(w)) dfs(w, seen, order);
}

int main() {
    vector<pair<string, string>> edges = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
    for (auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (auto& [v, list] : adj) sort(list.begin(), list.end()); // alphabetical neighbors
    vector<string> verts;
    for (auto& [v, list] : adj) verts.push_back(v);

    cout << "Adjacency list:\n";
    size_t degreeSum = 0;
    for (const string& v : verts) {
        cout << "  " << v << ": " << join(adj[v], " ") << "\n";
        degreeSum += adj[v].size();
    }
    cout << "Sum of degrees = " << degreeSum << " = 2 * " << edges.size() << " edges\n";

    map<string, int> dist = {{"A", 0}};
    vector<string> order;
    queue<string> q;
    q.push("A");
    while (!q.empty()) {
        string u = q.front();
        q.pop();
        order.push_back(u);
        for (const string& w : adj[u]) {
            if (!dist.count(w)) {
                dist[w] = dist[u] + 1;
                q.push(w);
            }
        }
    }
    cout << "BFS from A: " << join(order, " ") << "\n";
    vector<string> parts;
    for (const string& v : verts) parts.push_back(v + "=" + to_string(dist[v]));
    cout << "Edges from A: " << join(parts, ", ") << "\n";
    set<string> seen;
