function bfs(start) {
  const dist = { [start]: 0 }, order = [], queue = [start];
  while (queue.length) {
    const u = queue.shift();
    order.push(u);
    for (const w of adj[u]) {
      if (!(w in dist)) {
        dist[w] = dist[u] + 1;
        queue.push(w);
