// The standard library cannot print a 128-bit integer, so convert digit by digit
std::string toString(unsigned __int128 x) {
    std::string s;
    do {
        s.insert(s.begin(), static_cast<char>('0' + static_cast<int>(x % 10)));
        x /= 10;
    } while (x > 0);
    return s;
}

int main() {
    for (int n : {0, 1, 2, 3, 4, 5, 10, 15, 20}) std::printf("%2d! = %lld\n", n, factorial(n));
    std::printf("recursive rule: 20! == 20 * 19! -> %s\n", factorial(20) == 20 * factorial(19) ? "true" : "false");

    // Find the largest n with n! <= LLONG_MAX without ever overflowing
    const long long maxValue = std::numeric_limits<long long>::max();
    long long f = 1;
    int n = 0;
    while (f <= maxValue / (n + 1)) {
        n++;
        f *= n;
    }
    std::printf("largest n with n! <= 2^63-1: %d\n", n);

    unsigned __int128 exact = static_cast<unsigned __int128>(factorial(20)) * 21;
    // Signed overflow is undefined behavior in C++, so wrap through unsigned to show what hardware does
    auto wrapped = static_cast<long long>(static_cast<std::uint64_t>(factorial(20)) * 21u);
    std::printf("21! exactly          = %s\n", toString(exact).c_str());
    std::printf("long max (2^63-1)    = %lld\n", maxValue);
    std::printf("21! in a 64-bit long = %lld (overflowed, no error raised)\n", wrapped);
}

